// Scroll stories, shared by stop.html (shell.js: one car) and teaser.html (teaser.js: the teaser cars). Scrolled to, a car's
// stage (museum photo / 3-D model) pins, above the steps on a phone held upright and beside them otherwise, and only the
// steps move on: the introduction over the museum photo, one step per component with its cards (controls, legend,
// technical facts) in 3D, then background back on the photo with the car outline. The step at the reading line sets what
// the stage shows; only stages on screen run their frame loop.
import { t } from "./i18n.js";
import { h } from "./dom.js";
import { stageElement, mountViewer, caveats } from "./viewer.js";

// A step is its content and what the stage shows while it is at the reading line.
const step = (state, ...kids) => ({ state, el: h("section", { class: "step" }, kids) });

// One car's story, not yet playing. title: the tag of the car's title ("h1" on its own page); more: what closes the
// background step (the teaser's link to the stop page).
export function story(car, { title = "h2", more = null } = {}) {
  const first = car.components[0].id;
  const comps = car.components.map(c => step({ comp: c.id, view: "model", outline: false }, h("h3", {}, c.label)));
  const steps = [
    step({ comp: first, view: "photo", outline: false }, h("div", { class: "eyebrow" }, car.eyebrow), h(title, {}, car.title), h("p", { class: "lede" }, car.lede)),
    ...comps,
    step({ comp: first, view: "photo", outline: true }, h("footer", {}, h("h3", {}, t("Background")),
      h("p", {}, t("Back on the museum photo: the mechanism where it sits, inside the car's outline.")),
      car.note ? h("p", {}, car.note) : null, ...caveats(car), more)),
  ];
  steps[0].el.classList.add("on");
  const stageEl = stageElement(car);
  const el = h("article", { class: "story", "aria-label": car.name }, h("div", { class: "story-stage" }, stageEl), h("div", { class: "steps" }, steps.map(s => s.el)));
  return { car, el, stageEl, steps, comps, at: 0, viewer: null };
}

// Loads the stories' 3-D views (already in the page) and lets the scroll drive them. Returns one ?debug handle per story.
export async function play(stories) {
  await Promise.all(stories.map(async s => {
    try {
      s.viewer = await mountViewer(s.car, s.stageEl, comp => s.comps[s.car.components.indexOf(comp)].el);
      s.viewer.show(s.steps[0].state);
    } catch (err) {
      console.error(err);
      s.stageEl.append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
    }
  }));

  // The reading line: halfway down the screen beside the pinned stage, or halfway down the part it leaves free below it.
  // The last step whose top has passed the line is the one shown.
  function pick() {
    for (const s of stories) {
      const pane = s.stageEl.parentElement.getBoundingClientRect(), beside = s.steps[0].el.getBoundingClientRect().left >= pane.right;
      const line = beside ? innerHeight / 2 : (pane.bottom + innerHeight) / 2;
      let at = 0;
      s.steps.forEach((st, i) => { if (st.el.getBoundingClientRect().top < line) at = i; });
      if (at === s.at) continue;
      const before = s.steps[s.at].state;
      s.at = at;
      s.steps.forEach((st, i) => st.el.classList.toggle("on", i === at));
      if (s.viewer && s.steps[at].state !== before) s.viewer.show(s.steps[at].state);
    }
  }
  let queued = false;
  const schedule = () => { if (!queued) { queued = true; requestAnimationFrame(() => { queued = false; pick(); }); } };
  addEventListener("scroll", schedule, { passive: true });
  addEventListener("resize", schedule);
  pick();

  // Only stages on screen animate: several scenes at once, one of them a live wind tunnel, would be too much for a phone.
  const onScreen = new IntersectionObserver(entries => {
    for (const e of entries) { const v = stories.find(s => s.stageEl === e.target).viewer; if (e.isIntersecting) v.start(); else v.stop(); }
  });
  for (const s of stories) if (s.viewer) onScreen.observe(s.stageEl);

  return stories.map(s => ({
    slug: s.car.slug, step: () => s.at, state: () => s.viewer?.state,
    frames: () => s.viewer?.stage.stats.frames ?? 0, triangles: () => s.viewer?.stage.renderer.info.render.triangles ?? 0,
  }));
}
// Page shell for every stop: stop.html?s=<slug>[&r=teaser]. Builds the page from stops/tour.js + stops/<slug>/car.js: the
// car's scroll story (story.js), where it is on the route, and prev/next.
// With r=teaser (links from teaser.html) prev/next, the stop count and the back link stay within the teaser.
import tour, { teaser } from "../../stops/tour.js";
import { registerOffline } from "./offline.js";
import { t, loadCar, localizePage, missing } from "./i18n.js";
import { h, link } from "./dom.js";
import { story, play } from "./story.js";

const params = new URLSearchParams(location.search);
const slug = params.get("s");
const teaserStops = tour.filter(s => teaser.includes(s.slug));
const inTeaser = params.get("r") === "teaser" && teaserStops.some(s => s.slug === slug);
const route = inTeaser ? teaserStops : tour;
const idx = route.findIndex(s => s.slug === slug);   // validated before any dynamic import
const app = document.getElementById("app");

localizePage();
registerOffline();
if (inTeaser) Object.assign(document.getElementById("back"), { href: "teaser.html", textContent: t("← Highlights") });
if (idx < 0) {
  document.title = t("Stop not found · Museum tour");
  app.replaceChildren(h("h1", {}, t("Stop not found")), h("p", {}, t("This QR code or link does not match a stop on the tour."), " ", link("./", t("Open the tour route"))));
} else {
  main().catch(err => {
    console.error(err);
    app.append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
  });
}

async function main() {
  const stop = route[idx];
  const car = await loadCar(stop.slug);
  document.title = t("{0} · Museum tour", car.name);
  const prev = route[idx - 1], next = route[idx + 1], here = s => `stop.html?s=${s.slug}${inTeaser ? "&r=teaser" : ""}`;
  const nameOf = async s => (s ? (await loadCar(s.slug)).name : null);
  const [prevName, nextName] = await Promise.all([nameOf(prev), nameOf(next)]);
  const s = story(car, { title: "h1" });
  document.getElementById("where").textContent = t("Stop {0} of {1} · {2} · Level {3}", idx + 1, route.length, t(stop.room), stop.level);
  app.replaceChildren(s.el,
    h("nav", { class: "pager", "aria-label": t("Previous and next stop") },
      prev ? link(here(prev), `← ${prevName}`) : h("span"), next ? link(here(next), `${nextName} →`) : h("span")),
    h("p", { class: "note" }, t("Unofficial private tour notes, not affiliated with Mercedes-Benz. 3D: three.js (MIT). Mechanisms are original code from illustrative hardpoints.")));
  const handles = await play([s]);
  if (params.has("debug")) window.__tour = { stories: handles, missing: () => [...missing], ready: true };
}
// Teaser page (teaser.html): the teaser stops as scroll stories (story.js), one after the other. Each story links its stop
// page with &r=teaser, so the stop pages page between these stops.
import tour, { teaser } from "../../stops/tour.js";
import { showOfflineStatus } from "./offline.js";
import { t, loadCar, localizePage, missing } from "./i18n.js";
import { h } from "./dom.js";
import { story, play } from "./story.js";

localizePage();
showOfflineStatus(document.getElementById("status"));
const cars = await Promise.all(tour.filter(s => teaser.includes(s.slug)).map(s => loadCar(s.slug)));
const credits = [...new Set(cars.filter(c => c.photo).map(c => `${c.photo.credit.author} (${c.photo.credit.license})`))];
document.getElementById("credits").textContent = t("Photos via Wikimedia Commons: {0}; each car's page links its photo's source.", credits.join(", "));

const stories = cars.map(car => story(car, { more: h("a", { class: "pill primary", href: `stop.html?s=${car.slug}&r=teaser` }, t("Open this car on its own page")) }));
document.getElementById("cars").replaceChildren(...stories.map(s => s.el));
const handles = await play(stories);
if (new URLSearchParams(location.search).has("debug")) window.__tour = { stories: handles, missing: () => [...missing], ready: true };

// One stop's working view, shared by stop.html (shell.js) and teaser.html (teaser.js): the stage element over the museum
// photo, the ghost body, one subsystem per component with its panel cards and talking points, and the frame loop. The page
// chooses what is shown (the Component/View switches on a stop page, the scroll position on the teaser) and calls show().
import { createPanel } from "./panel.js";
import { h, link } from "./dom.js";
import { t } from "./i18n.js";

// The stage element alone, so a page can lay itself out before three.js loads. It keeps the photo's aspect.
export function stageElement(car) {
  const photo = car.photo;
  return h("div", { class: "stage", style: photo ? `--aspect:${photo.w}/${photo.h};--ar:${(photo.w / photo.h).toFixed(4)}` : null },
    photo ? h("img", { src: `stops/${car.slug}/${photo.src}`, alt: photo.alt, width: photo.w, height: photo.h, hidden: true }) : null,
    h("div", { class: "hint" }, t("drag to orbit · pinch to zoom")),
    photo ? h("div", { class: "credit", hidden: true }, t("Photo:"), " ", link(photo.credit.url, photo.credit.author), `, ${photo.credit.license}`) : null);
}

// The car's caveats and sources as two collapsed lists (empty ones left out).
export const caveats = car => [
  car.unverified?.length ? h("details", {}, h("summary", {}, t("Illustrative, not verified")), h("ul", {}, car.unverified.map(u => h("li", {}, u)))) : null,
  car.sources?.length ? h("details", {}, h("summary", {}, t("Sources")), h("ul", {}, car.sources.map(s => h("li", {}, link(s.url, s.label))))) : null,
];

// Loads three.js and the car's subsystems into stageEl (from stageElement). cardsFor(comp) is the element that takes that
// component's panel cards. show({ comp, view: "model" | "photo", outline }, resetOrbit) sets what the stage shows (a car
// without a photo shows its model instead); call it before start(). stop() pauses the loop. stage is exposed for ?debug (stats, renderer).
export async function mountViewer(car, stageEl, cardsFor) {
  const [{ createStage }, { buildGhost }] = await Promise.all([import("../scene/stage.js"), import("../scene/ghost-body.js")]);
  const img = stageEl.querySelector("img"), credit = stageEl.querySelector(".credit"), hint = stageEl.querySelector(".hint");
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const stage = createStage(stageEl, car);
  const carRoot = new stage.THREE.Group(); stage.scene.add(carRoot);
  const ghost = buildGhost(car.body?.ghost); carRoot.add(ghost.group);
  stage.onTheme(({ onPhoto }) => { const c = onPhoto ? new stage.THREE.Color(0xffffff) : stage.color("--fg"); ghost.fill.color.copy(c); ghost.edge.color.copy(c); });

  const instances = new Map();
  for (const comp of car.components) {
    if (!/^[a-z0-9-]+$/.test(comp.subsystem)) throw new Error(`bad subsystem id ${comp.subsystem}`);
    const mod = await import(`../../subsystems/${comp.subsystem}.js`);
    const panel = createPanel(cardsFor(comp), comp.id, `${car.slug}-${comp.id}`);
    const inst = mod.create({ stage, carRoot, frame: car.frame, ride: car.ride, panel, reducedMotion, t }, comp.params);
    panel([{ label: t("Technical facts about the car"), items: [{ list: comp.talk }] }]);
    instances.set(comp.id, inst);
  }

  let shown = null;
  function show(state, resetOrbit = true) {
    shown = { ...state, view: car.photo ? state.view : "model" };
    const onPhoto = shown.view === "photo", comp = car.components.find(c => c.id === shown.comp);
    if (img) { img.hidden = !onPhoto; credit.hidden = !onPhoto; }
    hint.hidden = onPhoto;
    ghost.group.visible = onPhoto ? shown.outline : (comp.ghost?.fill ?? 0) + (comp.ghost?.edge ?? 0) > 0;
    ghost.fill.opacity = onPhoto ? 0 : comp.ghost?.fill ?? 0.06;
    ghost.edge.opacity = onPhoto ? 0.7 : comp.ghost?.edge ?? 0.5;
    for (const [id, inst] of instances) inst.layout?.({ active: id === shown.comp, onPhoto });
    stage.setPhotoView(onPhoto);
    if (!onPhoto && resetOrbit) stage.setOrbit(comp.view);
  }
  return {
    show, stage,
    get state() { return shown; },
    stop: stage.stop,
    start() {
      stage.start(dt => {
        carRoot.position.set(0, 0, 0); carRoot.rotation.set(0, 0, 0);
        instances.get(shown.comp).update(dt, { onPhoto: shown.view === "photo" });
      });
    },
  };
}
// Service-worker registration shared by the index and every stop. On localhost / LAN addresses the SW is skipped (and any
// earlier one removed) so dev edits are never served stale; add ?sw=1 to test offline locally against a build in _site/.
import { t } from "./i18n.js";

const LOCAL = /^(localhost|127\.|\[::1\]|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)|\.local$/;

// onStatus(kind, info): kind = "ready" | "partial" | "dev" | "unsupported" | "error"; info = { version, total, cached }.
export function registerOffline(onStatus = () => {}) {
  if (!("serviceWorker" in navigator)) return onStatus("unsupported");
  const sw = navigator.serviceWorker;
  if (LOCAL.test(location.hostname) && !new URLSearchParams(location.search).has("sw")) {
    sw.getRegistrations().then(rs => rs.forEach(r => r.unregister()));
    return onStatus("dev");
  }
  const root = new URL("../../", import.meta.url);   // site root, where sw.js lives
  sw.register(new URL("sw.js", root)).then(() => sw.ready).then(reg => new Promise(resolve => {
    const ch = new MessageChannel();
    ch.port1.onmessage = e => resolve(e.data);
    reg.active.postMessage({ type: "status" }, [ch.port2]);
  })).then(s => onStatus(s.total > 0 && s.cached === s.total ? "ready" : "partial", s)).catch(err => { console.warn(err); onStatus("error"); });
}

// The route pages' status line (index.html, teaser.html): what registerOffline reports, asked again while files are stored.
export function showOfflineStatus(el) {
  registerOffline(function show(kind, s) {
    el.textContent = {
      ready: t("Ready offline ✓ — every stop is stored on this device."),
      partial: t("Storing the tour for offline use… ({0} of {1} files)", s?.cached ?? 0, s?.total ?? "?"),
      dev: t("Offline mode is off on this development server (add ?sw=1 to a built copy to test it)."),
      unsupported: t("This browser cannot store the tour offline; keep a signal."),
      error: t("Offline storage failed; the tour still works with a signal. Reload to retry."),
    }[kind];
    el.classList.toggle("ready", kind === "ready");
    if (kind === "partial") setTimeout(() => registerOffline(show), 1500);
  });
}
// Offline cache for the whole tour. tools/build.mjs stamps VERSION (content hash) and FILES (every site file) into the copy
// in _site/; this source copy precaches nothing. Install caches every stop, so one visit with signal covers the museum.
const VERSION = "dev";
const FILES = [];
const CACHE = `tour-${VERSION}`;

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith("tour-") && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// Cache first: in the museum a weak signal is worse than none, so never wait on the network for a cached file.
self.addEventListener("fetch", e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return;
  const page = req.mode === "navigate" || /\/(stop|index|teaser)\.html$|\/$/.test(url.pathname);
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: page });   // stop.html?s=… is one cached page
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok && res.type === "basic") cache.put(req, res.clone());
      return res;
    } catch (err) {
      if (page) return (await cache.match("index.html")) ?? Response.error();
      throw err;
    }
  })());
});

self.addEventListener("message", e => {
  if (e.data?.type !== "status") return;
  e.waitUntil(caches.open(CACHE).then(async cache => {
    let cached = 0;
    for (const f of FILES) if (await cache.match(f)) cached++;
    e.ports[0].postMessage({ version: VERSION, total: FILES.length, cached });
  }));
});
// Build the deployable site into _site/: copy the site files, then stamp the service worker with a content-hash VERSION
// and the full precache list, so one visit stores every stop. Node built-ins only. Usage: node tools/build.mjs
import { cp, rm, mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url)), out = join(root, "_site");
const ENTRIES = ["index.html", "teaser.html", "stop.html", "sw.js", "manifest.webmanifest", "teaser.webmanifest", "icons", "lib", "stops", "subsystems", "vendor"];
const SKIP = /(^|\/)\.|\.svg$/;   // dotfiles (.DS_Store) and the icon source

await rm(out, { recursive: true, force: true });
await mkdir(out);
for (const e of ENTRIES) await cp(join(root, e), join(out, e), { recursive: true, filter: src => !SKIP.test(src.slice(root.length)) });

async function walk(dir, base = "") {
  const files = [];
  for (const d of await readdir(join(dir, base), { withFileTypes: true })) {
    const rel = base ? `${base}/${d.name}` : d.name;
    if (d.isDirectory()) files.push(...await walk(dir, rel)); else files.push(rel);
  }
  return files;
}

const files = (await walk(out)).filter(f => f !== "sw.js").sort();
const hash = createHash("sha256");
let bytes = 0;
for (const f of files) { const b = await readFile(join(out, f)); bytes += b.length; hash.update(f).update(b); }
const version = hash.digest("hex").slice(0, 12);

const swPath = join(out, "sw.js"), sw = await readFile(swPath, "utf8");
const list = ["./", ...files.map(f => `./${f}`)];
const stamped = sw.replace('const VERSION = "dev";', `const VERSION = "${version}";`).replace("const FILES = [];", `const FILES = ${JSON.stringify(list)};`);
if (stamped === sw || !stamped.includes(version) || stamped.includes("const FILES = [];")) throw new Error("sw.js: VERSION/FILES placeholders not found");
await writeFile(swPath, stamped);
console.log(`_site: ${files.length} files, ${(bytes / 1024).toFixed(0)} KB, version ${version}`);

// Every stop on the route loads, renders and animates, and scrolling its story sets what the stage shows, on each emulated
// device.
import { test, expect } from "@playwright/test";
import tour, { teaser } from "../../stops/tour.js";
import { watchErrors, stepsOf, shown } from "./helpers.mjs";

const cars = await Promise.all(tour.map(async s => (await import(`../../stops/${s.slug}/car.js`)).default));

for (const car of cars) {
  test(`${car.slug}: the story's steps set the stage, readouts move`, async ({ page }) => {
    const errors = watchErrors(page);
    await page.goto(`stop.html?s=${car.slug}&debug`);
    await page.waitForFunction(() => window.__tour?.stories[0].frames() > 10, null, { timeout: 20_000 });
    await expect(page.locator(".step")).toHaveCount(car.components.length + 2);

    const pinned = new Set();
    for (const [k, want] of stepsOf(car).entries()) {
      const step = page.locator(".step").nth(k);
      await step.evaluate(s => s.scrollIntoView({ block: "center" }));
      await expect.poll(() => shown(page)).toEqual({ step: k, state: want });
      await expect(page.locator(".stage img")).toBeVisible({ visible: want.view === "photo" });
      if (k === 0 || k > car.components.length) continue;   // intro and background: no component cards
      pinned.add(await page.locator(".stage").evaluate(s => Math.round(s.getBoundingClientRect().top)));
      await expect.poll(() => page.evaluate(() => window.__tour.stories[0].triangles())).toBeGreaterThan(0);
      const readouts = () => step.locator(`.panel[data-comp="${want.comp}"] output`).allTextContents();
      const before = await readouts();
      expect(before.length).toBeGreaterThan(0);
      await expect.poll(readouts, { timeout: 15_000 }).not.toEqual(before);
    }
    expect(pinned.size, "stage stays put through the component steps").toBe(1);

    const fit = await page.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, w: innerWidth, h: innerHeight, stage: document.querySelector(".stage").getBoundingClientRect().height }));
    expect(fit.scrollW, "no horizontal scroll").toBeLessThanOrEqual(fit.w);
    expect(fit.stage, "stage fits the viewport height").toBeLessThanOrEqual(fit.h);
    expect(errors).toEqual([]);
  });
}

