    await route.filter({hasText:'Gullwing'}).first().click()
    const frameButton = p.getByRole('button',{name:'Cut down for normal doors'})
    await frameButton.waitFor()
    const compare = p.locator('.step').nth(1)
    console.log('frame', await compare.locator('output').allTextContents())
    await frameButton.click()
    await p.waitForTimeout(300)
    console.log('cut down',await compare.locator('output').allTextContents(), 'selected',await frameButton.getAttribute('aria-pressed'))
    console.log('facts position after tap', await compare.locator('.talk').evaluate(el=>Math.round(el.getBoundingClientRect().top)))
    await p.screenshot({path:'/private/tmp/museum-visitor-frame.png'})
    await p.locator('.step').last().locator('summary').first().click()
    console.log('background', await p.locator('.step').last().innerText())
    await p.goto(url+'stop.html?s=slk&debug')
    await p.getByRole('button',{name:'Open the roof'}).click()
