    await p.goto(url+'teaser.html?debug')
    await p.waitForFunction(()=>window.__tour?.ready)
    console.log('highlights',await p.locator('.story h2').allTextContents())
    console.log('teaser stages', await p.locator('.stage canvas').count())
  } finally {await browser.close()}
}
